from collect import add_metric

def test_metric_no_leak():
    first = add_metric("x", 1)
    second = add_metric("y", 2)
    assert first == {"x": [1]}
    assert second == {"y": [2]}

def test_metric_explicit_store():
    store = {}
    add_metric("x", 1, store)
    add_metric("x", 2, store)
    assert store == {"x": [1, 2]}

def test_metric_empty_call():
    assert add_metric("x", 0) == {"x": [0]}


from parsing import parse_csv_line

def test_csv_quoted_comma():
    assert parse_csv_line('1,"x,y",3') == ["1", "x,y", "3"]

def test_csv_trailing_empty():
    assert parse_csv_line("a,b,") == ["a", "b", ""]

def test_csv_single():
    assert parse_csv_line("only") == ["only"]

def test_csv_quoted_semicolon():
    assert parse_csv_line('"a;b",c') == ["a;b", "c"]
